const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for 8 serial digits (see docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/** True for `XX#########AT`: 2 letters, 8 digits, a correct check digit, country code AT. Expects upper case. */
export function isValidAustrianPostS10(trackingNumber: string): boolean {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(trackingNumber);
  return match !== null && s10CheckDigit(match[1]) === Number(match[2]);
}
